const entries = $input.item.json.entries || [];
const yesterday = new Date(Date.now() - 86400000).toISOString();
const recent = entries.filter(e => e.timestamp > yesterday);
const byType = {};
recent.forEach(e => { byType[e.event_type] = (byType[e.event_type] || 0) + 1; });
const topUsers = {};
recent.forEach(e => { topUsers[e.principal_id] = (topUsers[e.principal_id] || 0) + 1; });
const topUsersList = Object.entries(topUsers).sort((a,b) => b[1]-a[1]).slice(0,5).map(([u,c]) => u + ': ' + c);
const searchCount = byType.search || 0;
const ingestCount = byType.ingest || 0;
const syncCount = byType.connector || 0;
return [{ json: { total: recent.length, byType, topUsersList, searchCount, ingestCount, syncCount, date: new Date().toLocaleDateString() } }];

const digest = $('Compute Digest Stats').item.json;
const readiness = $('GET /api/v1/readiness').item.json;
const checks = readiness.checks || {};
const healthLines = Object.entries(checks).map(([k,v]) => (v === 'ok' ? ':white_check_mark:' : ':x:') + ' ' + k + ': ' + v).join('\n');
const topUsersText = digest.topUsersList.length ? digest.topUsersList.join(', ') : 'none';
const message = [
  ':bar_chart: *AegisMind Daily Digest — ' + digest.date + '*',
  '',
  '*Activity (last 24h)*',
  ':mag: Searches: *' + digest.searchCount + '*',
  ':inbox_tray: Ingestions: *' + digest.ingestCount + '*',
  ':arrows_counterclockwise: Connector Syncs: *' + digest.syncCount + '*',
  ':busts_in_silhouette: Top Users: ' + topUsersText,
  '',
  '*System Health*',
  healthLines
].join('\n');
return [{ json: { text: message } }];
